SELECT percentile_cont(0.75) within GROUP (ORDER BY num_procedures) - percentile_cont(0.25) within GROUP (ORDER BY num_procedures) AS interquartile_range FROM (SELECT p.hadm_id, COUNT(DISTINCT p_icd.icd_code) AS num_procedures FROM patients p JOIN procedures_icd p_icd ON p.subject_id = p_icd.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM p.dob) = 1957 AND EXTRACT(YEAR FROM age(p.dob)) BETWEEN 52 AND 62 GROUP BY p.hadm_id) AS procedures;